  if(!replay&&mode==='trail'){if(state.levelId>=LEVEL_COUNT){trailMap(11);return;}startLevel(state.levelId+1);return;}
  state=replay?createGame({mode:state.mode,round:state.round,seed:state.seed,theme:state.theme,date:state.date,levelId:state.levelId||1,difficulty:state.difficulty,surprises:state.surprises,size:state.size}):make(mode,state.mode===mode?state.round+1:1,{size:state.size||144});
