  $('#round-label').textContent=state.mode==='daily'?'THE DAILY SORT':state.mode==='rush'?'A LIVELIER DELIVERY':state.mode==='trail'?'THE NEIGHBORHOOD TRAIL':state.mode==='pantry'?'THE BIG, SLOW SORT':'MORNING DELIVERY';
