$('#focus-button').addEventListener('click',()=>{profile.settings.focus=true;render();save();window.scrollTo({top:0,behavior:'instant'});});$('#exit-focus').addEventListener('click',()=>{profile.settings.focus=false;render();save();});$('#install-button').addEventListener('click',installHelp);
$('#trail-button').addEventListener('click',()=>puzzleMap());$('#pantry-button').addEventListener('click',otherModes);$('#collection-button').addEventListener('click',()=>journal('collection'));$('#home-button').addEventListener('click',()=>journal('shop'));$('#lantern-button').addEventListener('click',()=>useLantern().catch(actionError));$('#specials').addEventListener('click',e=>{if(e.target.closest('[data-action="puzzle-help"]')){shelfHelp();return;}const b=e.target.closest('[data-mechanic]');if(b)mechanicHelp(b.dataset.mechanic);});
$('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('cancel',e=>{if(state.status!=='playing'&&state.mode!=='puzzle')e.preventDefault();});$('#modal').addEventListener('close',()=>{paused=$('#modal').open;lastTick=performance.now();if(!paused&&prevFocus?.isConnected)prevFocus.focus({preventScroll:true});});
$('#modal').addEventListener('click',e=>{
  const a=e.target.closest('[data-action]');
  if(a){const actions={puzzles:()=>puzzleMap(),'resume-puzzle':()=>loadMode('puzzle'),'puzzle-jump':()=>startPuzzle($('#puzzle-jump').value),'puzzle-help':shelfHelp,'other-modes':otherModes,'pantry-menu':pantryMenu,'classic-trail':()=>trailMap(),daily:()=>loadMode('daily'),rush:()=>loadMode('rush'),close:()=>state.status==='won'?showWin(false):state.status==='timeout'?showTimeout():closeModal(),settings,journal:()=>journal('shop'),'restart-confirm':restartConfirm,next:()=>newRound(),replay:()=>newRound(state.mode,true),cozy:()=>loadMode('cozy'),share,results:()=>showWin(false),trail:()=>trailMap(),jump:()=>startLevel($('#level-jump').value),'resume-pantry':()=>loadMode('pantry'),'resume-trail':()=>loadMode('trail'),backup:exportProgress,'download-backup':downloadBackup,'copy-backup':copyBackup,'paste-import':pasteImport,'review-import':()=>reviewImport($('#import-text').value),install:async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else installHelp();},import:()=>$('#backup-file').click(),'confirm-import':()=>{if(pendingImport){profile=pendingImport;pendingImport=null;state=null;history=[];loadMode(profile.mode);toast('Your little shop is right where you left it.');}},'stop-flow':()=>{clearTimeout(flowTimer);$('.flow-note').textContent='All the time you need. Continue whenever you’re ready.';},untimed:()=>{state.status='playing';state.clockDisabled=true;history=[];closeModal();render();save();toast('All the time you need. Your Cozy delivery is saved separately.');}};Promise.resolve().then(()=>actions[a.dataset.action]?.()).catch(actionError);return;}
  const puzzle=e.target.closest('[data-puzzle-level]');if(puzzle){startPuzzle(+puzzle.dataset.puzzleLevel);return;}
  const puzzleCh=e.target.closest('[data-puzzle-chapter]');if(puzzleCh){puzzleMap(+puzzleCh.dataset.puzzleChapter);return;}
  const level=e.target.closest('[data-level]');if(level){startLevel(+level.dataset.level);return;}
  const chapter=e.target.closest('[data-chapter]');if(chapter){trailMap(+chapter.dataset.chapter);return;}
  const tab=e.target.closest('[data-journal]');if(tab){journal(tab.dataset.journal);return;}
  const pantry=e.target.closest('[data-pantry]');if(pantry){startPantry(+pantry.dataset.pantry);return;}
  const theme=e.target.closest('[data-theme-choice]');if(theme&&THEMES[theme.dataset.themeChoice]){profile.settings.theme=theme.dataset.themeChoice;render();save();settings();return;}
  const decor=e.target.closest('[data-decor]');if(decor&&DECOR.some(d=>d.id===decor.dataset.decor&&profile.completed>=d.requirement)){profile.settings.decor=decor.dataset.decor;save();journal('shop');return;}
  const favorite=e.target.closest('[data-favorite]');if(favorite){const t=+favorite.dataset.favorite;if(!profile.collection[t])return;if(profile.favorites.includes(t))profile.favorites=profile.favorites.filter(x=>x!==t);else if(profile.favorites.length>=4){toast('Four little favorites fit here. Unpin one to make a little room.');return;}else profile.favorites.push(t);save();const scroll=$('#modal').scrollTop;journal('collection');$('#modal').scrollTop=scroll;}
});
$('#modal').addEventListener('change',e=>{
  const key=e.target.dataset.setting;
  if(['sound','focus','motion','labels','surprises','flow'].includes(key))profile.settings[key]=e.target.checked;
  else if(key==='volume')profile.settings.volume=Number(e.target.value);
  else if(['difficulty','ambience'].includes(key))profile.settings[key]=e.target.value;else return;
  applySettings();save();if(key==='sound')sound(true);if(['ambience','volume'].includes(key))setAmbience(profile.settings);
});
