document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||$('#modal').open||/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'&&state.mode==='puzzle'){clearShelfSelection();render();}if(e.key.toLowerCase()==='u'){e.preventDefault();undo();}if(e.key.toLowerCase()==='h'){e.preventDefault();showHint();}if(e.code==='Space'&&e.target===document.body&&state.mode==='rush'){e.preventDefault();pause();}});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden){clearTimeout(flowTimer);setAmbience(profile.settings,false);save();}else {setAmbience(profile.settings);if(state.mode==='rush'&&state.started&&state.status==='playing'&&!$('#modal').open)pause();}});
window.addEventListener('blur',()=>{if(state.mode==='rush'&&state.started&&state.status==='playing'&&!$('#modal').open)pause();});
window.addEventListener('pagehide',save);
setInterval(()=>{const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;if(paused||document.hidden)return;tick(state,Math.min(delta,1));renderClock();if(state.status==='timeout'&&!$('#modal').open){save();showTimeout();}},200);
setInterval(save,5000);
loadMode(MODES.includes(profile.mode)?profile.mode:'puzzle');
document.addEventListener('pointerdown',()=>setAmbience(profile.settings),{once:true});

