  const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  const read=()=>({mode:state.mode,rules:state.mode==='puzzle'?'Move one good to an empty slot on another shelf. Three on a shelf clear. Matching a key good opens its shelf.':'Pick three goods into the basket.',moves:state.moves,hints:state.hints,target:state.spec.target,selection:selected,shelves:state.mode==='puzzle'?state.shelves.map((s,i)=>({shelf:i,front:s.rows[0],next:s.rows[1]||[],locked:!!s.lock,key:s.key===null?null:GOODS[s.key].name})):undefined,freeSpaces:state.mode==='puzzle'?shelfSpaces(state.shelves):undefined,round:state.round,level:state.levelId,status:state.status,paused,mechanics:state.spec.mechanics,lanterns:state.lanterns,order:state.order,visible:visible(state).map(p=>({...p,name:GOODS[p.type].name})),basket:state.tray.map(t=>GOODS[t].name),matches:state.matches,totalMatches:state.total/3});
