function installHelp(){openModal(`<div class="win-emblem" aria-hidden="true">⌂</div><div class="modal-eyebrow">A LITTLE LOCAL, WHEREVER YOU ARE</div><h2 class="modal-title" id="modal-title">Keep a little calm close.</h2><p class="modal-copy">Open Little Local in Safari on your iPhone. Tap Share, then Add to Home Screen. Keep Open as Web App on, and tap Add.</p><p class="modal-copy compact">Your first visit needs a connection. No account is needed. Once the game says “Ready offline” below, its shelves can come along without a connection. Browser storage can be cleared by your device; export progress from My records for a keepsake copy.</p><p class="modal-copy compact">${offlineReady?'✓ This browser has saved the game for offline play.':'The game is preparing its offline files, if this browser supports them.'}</p>${installPrompt?'<button class="primary-button" data-action="install">Add Little Local to this device</button>':''}<button class="primary-button" data-action="close">Lovely, thank you</button><a class="install-reference" href="https://support.apple.com/guide/iphone/open-as-web-app-iphea86e5236/ios" target="_blank" rel="noopener">Apple’s Home Screen instructions ↗</a>`);}
